// Requirement: User must have a specific permission
public class PermissionRequirement : IAuthorizationRequirement
{
    public string Permission { get; }

    public PermissionRequirement(string permission)
    {
        Permission = permission ?? throw new ArgumentNullException(nameof(permission));
    }
}

// Requirement: User must belong to an approved domain
public class DomainRequirement : IAuthorizationRequirement
{
    public string[] AllowedDomains { get; }

    public DomainRequirement(params string[] allowedDomains)
    {
        AllowedDomains = allowedDomains;
    }
}

public class PermissionHandler : 
    AuthorizationHandler<PermissionRequirement>
{
    private readonly UserManager<ApplicationUser> _userManager;

    public PermissionHandler(UserManager<ApplicationUser> userManager)
    {
        _userManager = userManager;
    }

    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        PermissionRequirement requirement)
    {
        var user = await _userManager.GetUserAsync(context.User);
        if (user == null)
        {
            return; // No user, deny by default
        }

        var claims = await _userManager.GetClaimsAsync(user);
        var hasPermission = claims.Any(c => 
            c.Type == "Permission" && 
            c.Value == requirement.Permission);

        if (hasPermission)
        {
            context.Succeed(requirement);
        }
    }
}

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("RequireAdmin", policy =>
        policy.RequireRole("Admin"));

    options.AddPolicy("RequireReportAccess", policy =>
        policy.RequireClaim("Permission", "report:read", "report:export"));

    options.AddPolicy("RequireEngineeringAccess", policy =>
    {
        policy.RequireClaim("Department", "Engineering");
        policy.RequireClaim("ClearanceLevel", "5");
        policy.Requirements.Add(new DomainRequirement("internal", "secure"));
    });
});

