[Authorize(Policy = "RequireDocumentAccess")]
public async Task<IActionResult> GetDocument(string documentId)
{
    // Access granted by policy handler
    var doc = await _service.GetDocumentAsync(documentId);
    return Ok(doc);
}

public class DocumentsController : ControllerBase
{
    private readonly IAuthorizationService _authService;

    public DocumentsController(IAuthorizationService authService)
    {
        _authService = authService;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateDocument(string id, UpdateDto dto)
    {
        var document = await _dbContext.Documents.FindAsync(id);
        if (document == null) return NotFound();

        // Authorize based on the actual resource
        var result = await _authService.AuthorizeAsync(
            User, document, "CanEditDocument");

        if (!result.Succeeded)
        {
            return Forbid();
        }

        document.Title = dto.Title;
        document.Content = dto.Content;
        await _dbContext.SaveChangesAsync();
        return NoContent();
    }
}

// C# Example with Modern Patterns
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace Example
{
    // Generic repository interface
    public interface IRepository<T> where T : class
    {
        Task<T?> GetByIdAsync(int id);
        Task<IEnumerable<T>> GetAllAsync();
        Task<T> CreateAsync(T entity);
        Task UpdateAsync(T entity);
        Task DeleteAsync(int id);
    }

    // Service with dependency injection
    public class UserService
    {
        private readonly IRepository<User> _repository;
        private readonly ILogger<UserService> _logger;

        public UserService(
            IRepository<User> repository,
            ILogger<UserService> logger)
        {
            _repository = repository;
            _logger = logger;
        }

        public async Task<User?> GetUserWithOrdersAsync(int userId)
        {
            try
            {
                _logger.LogInformation("Fetching user {UserId}", userId);
                var user = await _repository.GetByIdAsync(userId);

                if (user == null)
                {
                    _logger.LogWarning("User {UserId} not found", userId);
                    return null;
                }

                return user;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching user {UserId}", userId);
                throw;
            }
        }
    }
}
